"""MSX-BASIC detokenizer: python detok.py file.bas"""
import sys, struct
T = {0x81:'END',0x82:'FOR',0x83:'NEXT',0x84:'DATA',0x85:'INPUT',0x86:'DIM',0x87:'READ',0x88:'LET',0x89:'GOTO',0x8A:'RUN',0x8B:'IF',0x8C:'RESTORE',0x8D:'GOSUB',0x8E:'RETURN',0x8F:'REM',0x90:'STOP',0x91:'PRINT',0x92:'CLEAR',0x93:'LIST',0x94:'NEW',0x95:'ON',0x96:'WAIT',0x97:'DEF',0x98:'POKE',0x99:'CONT',0x9A:'CSAVE',0x9B:'CLOAD',0x9C:'OUT',0x9D:'LPRINT',0x9E:'LLIST',0x9F:'CLS',0xA0:'WIDTH',0xA1:'ELSE',0xA2:'TRON',0xA3:'TROFF',0xA4:'SWAP',0xA5:'ERASE',0xA6:'ERROR',0xA7:'RESUME',0xA8:'DELETE',0xA9:'AUTO',0xAA:'RENUM',0xAB:'DEFSTR',0xAC:'DEFINT',0xAD:'DEFSNG',0xAE:'DEFDBL',0xAF:'LINE',0xB0:'OPEN',0xB1:'FIELD',0xB2:'GET',0xB3:'PUT',0xB4:'CLOSE',0xB5:'LOAD',0xB6:'MERGE',0xB7:'FILES',0xB8:'LSET',0xB9:'RSET',0xBA:'SAVE',0xBB:'LFILES',0xBC:'CIRCLE',0xBD:'COLOR',0xBE:'DRAW',0xBF:'PAINT',0xC0:'BEEP',0xC1:'PLAY',0xC2:'PSET',0xC3:'PRESET',0xC4:'SOUND',0xC5:'SCREEN',0xC6:'VPOKE',0xC7:'SPRITE',0xC8:'VDP',0xC9:'BASE',0xCA:'CALL',0xCB:'TIME',0xCC:'KEY',0xCD:'MAX',0xCE:'MOTOR',0xCF:'BLOAD',0xD0:'BSAVE',0xD1:'DSKO$',0xD2:'SET',0xD3:'NAME',0xD4:'KILL',0xD5:'IPL',0xD6:'COPY',0xD7:'CMD',0xD8:'LOCATE',0xD9:'TO',0xDA:'THEN',0xDB:'TAB(',0xDC:'STEP',0xDD:'USR',0xDE:'FN',0xDF:'SPC(',0xE0:'NOT',0xE1:'ERL',0xE2:'ERR',0xE3:'STRING$',0xE4:'USING',0xE5:'INSTR',0xE6:"'",0xE7:'VARPTR',0xE8:'CSRLIN',0xE9:'ATTR$',0xEA:'DSKI$',0xEB:'OFF',0xEC:'INKEY$',0xED:'POINT',0xEE:'>',0xEF:'=',0xF0:'<',0xF1:'+',0xF2:'-',0xF3:'*',0xF4:'/',0xF5:'^',0xF6:'AND',0xF7:'OR',0xF8:'XOR',0xF9:'EQV',0xFA:'IMP',0xFB:'MOD',0xFC:chr(92)}
F = {0x81:'LEFT$',0x82:'RIGHT$',0x83:'MID$',0x84:'SGN',0x85:'LOG',0x86:'SQR',0x87:'EXP',0x88:'COS',0x89:'SIN',0x8A:'TAN',0x8B:'ATN',0x8C:'FRE',0x8D:'INP',0x8E:'POS',0x8F:'LEN',0x90:'STR$',0x91:'VAL',0x92:'ASC',0x93:'CHR$',0x94:'PEEK',0x95:'VPEEK',0x96:'SPACE$',0x97:'OCT$',0x98:'HEX$',0x99:'LPOS',0x9A:'BIN$',0x9B:'CINT',0x9C:'CSNG',0x9D:'CDBL',0x9E:'FIX',0x9F:'STICK',0xA0:'STRIG',0xA1:'PDL',0xA2:'PAD',0xA3:'DSKF',0xA4:'FPOS',0xA5:'CVI',0xA6:'CVS',0xA7:'CVD',0xA8:'EOF',0xA9:'LOC',0xAA:'LOF',0xAB:'MKI$',0xAC:'MKS$',0xAD:'MKD$',0xAE:'ABS',0xAF:'INT',0xB0:'RND'}
def detok(d):
    assert d[0]==0xFF
    p=1; out=[]
    while True:
        if p+4>len(d): break
        nxt, ln = struct.unpack('<HH', d[p:p+4])
        if nxt==0: break
        q=p+4; s=''
        while d[q]!=0:
            b=d[q]
            if b==0x22:
                e=d.index(0x22,q+1) if 0x22 in d[q+1:d.index(0,q)] else d.index(0,q)
                s+=d[q:e+1].decode('latin1'); q=e+1; continue
            if b==0x3A and d[q+1]==0xA1 and d[q+2]==0xE6: s+="'"; q+=3; continue
            if b==0x3A and d[q+1]==0xA1: s+=':ELSE'; q+=2; continue
            if b==0xFF: s+=F.get(d[q+1],'?F%02X'%d[q+1]); q+=2; continue
            if b==0x0B: s+='&O%o'%struct.unpack('<H',d[q+1:q+3]); q+=3; continue
            if b==0x0C: s+='&H%X'%struct.unpack('<H',d[q+1:q+3]); q+=3; continue
            if b==0x0E: s+=str(struct.unpack('<H',d[q+1:q+3])[0]); q+=3; continue
            if b==0x0F: s+=str(d[q+1]); q+=2; continue
            if 0x11<=b<=0x1A: s+=str(b-0x11); q+=1; continue
            if b==0x1C: s+=str(struct.unpack('<h',d[q+1:q+3])[0]); q+=3; continue
            if b==0x1D or b==0x1F: s+='<fp>'; q+=5 if b==0x1D else 9; continue
            if b in T: s+=T[b]; q+=1; continue
            s+=chr(b); q+=1
        out.append('%d %s'%(ln,s)); p=nxt-0x8001 if nxt>=0x8001 else p
        # next pointer is an absolute memory address: recompute by scanning
        p = q+1
    return '\n'.join(out)
if __name__=='__main__':
    print(detok(open(sys.argv[1],'rb').read()))
